import { PARENT_SECTOR_LABELS_LIVE } from '@sdk/sectors.sdk'
/** طلبات الموافقة (مشتركة: مسؤول القاطع، الميدانية، المعاون، المدير المفوض): مهام الموافقة المعلّقة لديّ (إجازات/زمنيات/مستلزمات 00162 /إنهاء خدمة 00163 /سلف 00191)
 * حسب سلاسل الموافقات؛ موافقة أو رفض بسبب إلزامي؛ مسار الطلب. السلفة: يمكن للمعتمِد تعديل المبلغ (وعدد الأقساط) قبل الموافقة. */
import { lazy, Suspense, useState } from 'react'
import { PlatformResetDetailView } from '@features/platform-reset'
import { Archive, CheckCircle2, FileText, Download, Clock, Package, UserCheck, UserX, Wallet, XCircle } from 'lucide-react'
import { useApprovalTimeline, useDecideApproval, useMyApprovalTasks } from '@features/sector-manager/hooks'
import { useDecideAdvance } from '@features/advances/hooks'
import { STATUS_AR, dateAr, hm, timeAr } from '@features/sector-manager/format'
import type { AdvanceTaskDetails, ApprovalTask, AttendanceEditTaskDetails, BackdatedTaskDetails, ColdPurgeTaskDetails, ComplaintReportTaskDetails, HireTaskDetails, PlatformResetTaskDetails, TerminationTaskDetails } from '@sdk/sector-manager.sdk'
import { useComplaintReportDownload } from '@features/complaints/hooks/useComplaints'
import { ATTENDANCE_STATUS_LABELS } from '@features/hr/types'
import { LoadingSpinner } from '@components/feedback/LoadingSpinner'
import { fmtMoney } from '@portals/hr/components/hr-format'
import { ExecPageHeader } from '@components/executive/ExecPageHeader'

/** 00336: لوحة التفويض تُحمَّل عند الطلب فقط */
const DisclosureDetailDrawer = lazy(() => import('@features/disclosures/components/DisclosureDetailDrawer').then((m) => ({ default: m.DisclosureDetailDrawer })))
const DelegationPanel = lazy(() => import('@components/approvals/DelegationPanel').then((m) => ({ default: m.DelegationPanel })))
const PARENT_AR: Record<string, string> = PARENT_SECTOR_LABELS_LIVE   // 00394
const KIND_GROUPS: Array<[string, ApprovalTask['request_kind'][]]> = [['إجازات وزمنيات', ['leave', 'time_permit']], ['سلف', ['advance']], ['إنهاء خدمة ومستلزمات', ['termination', 'supplies', 'disclosure']], ['حذف أرشيف', ['cold_archive_purge']], ['تقارير الشكاوى', ['complaint_report']], ['تعيين موظف', ['hire']], ['تعديل حضور', ['attendance_edit']], ['تصفير المنصة', ['platform_reset']]]
/** `hero` مقبول للتوافق فقط — الرأس الموحد صار الوضع الوحيد (00227). */
export default function TeamRequestsPage({ title = 'طلبات فريقي' }: { title?: string; hero?: boolean }) {
  const tasks = useMyApprovalTasks()
  const list = tasks.data ?? []
  const [showDelegation, setShowDelegation] = useState(false)
  return (
    <div className="space-y-4 pb-4" data-testid="sm-requests">
      <ExecPageHeader icon="check-square" title={title} subtitle="الطلبات التي وصلت إلى دورك في سلسلة الموافقات — الرفض يُنهي الطلب، والموافقة تنقله للخطوة التالية أو تُنفّذه"
        stats={[{ label: 'بانتظار قرارك', value: tasks.isLoading ? '…' : tasks.isError ? '—' : list.length, tone: tasks.isError ? 'plain' : list.length ? 'red' : 'green', testId: 'approvals-pending' }, ...KIND_GROUPS.map(([label, kinds]) => ({ label, value: list.filter((t) => kinds.includes(t.request_kind)).length }))]} />
      <div className="flex justify-end">
        <button type="button" data-testid="delegation-toggle" className="inline-flex items-center gap-1 rounded-xl border bg-white px-3 py-2 text-sm font-bold text-emerald-800" onClick={() => setShowDelegation((v) => !v)}><UserCheck className="h-4 w-4" /> {showDelegation ? 'إخفاء التفويض' : 'تفويض موافقاتي أثناء غيابي'}</button>
      </div>
      {showDelegation && <Suspense fallback={<LoadingSpinner />}><DelegationPanel /></Suspense>}
      {tasks.isLoading ? <LoadingSpinner /> : tasks.isError ? (
        <div role="alert" className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">تعذر تحميل طلبات الموافقة. <button type="button" className="font-bold underline" onClick={() => void tasks.refetch()}>إعادة المحاولة</button></div>
      ) : (tasks.data ?? []).length === 0 ? (
        <div className="rounded-2xl border border-dashed bg-white p-8 text-center text-sm text-slate-500" data-testid="sm-requests-empty">لا طلبات بانتظار قرارك الآن.</div>
      ) : (
        <ul className="space-y-3" data-testid="sm-requests-list">
          {(tasks.data ?? []).map((t) => <TaskCard key={t.task_id} t={t} />)}
        </ul>
      )}
    </div>
  )
}

type Decider = { pending: boolean; approve: (x: { amount: number | null; installments: number | null }) => void; reject: (note: string, onSuccess: () => void) => void }
/** بطاقة المهمة: السلفة تستخدم advance_decide (مع تعديل المبلغ)؛ البقية approval_decide_request — الخطاف يُستدعى في المغلّف المناسب فقط */
function TaskCard({ t }: { t: ApprovalTask }) {
  return t.request_kind === 'disclosure' ? <DisclosureTaskCard t={t} /> : t.request_kind === 'advance' ? <AdvanceTaskCard t={t} /> : t.request_kind === 'platform_reset' ? <PlatformResetTaskCard t={t} /> : <GenericTaskCard t={t} />
}
/** الكشف يُفتح في درج القرار المعتمد، ولا يعتمد من بطاقة عامة. */
function DisclosureTaskCard({ t }: { t: ApprovalTask }) {
  const [open, setOpen] = useState(false)
  const details = t.details as { target_label?: string; amount?: number | null } | null
  return (
    <li className="rounded-2xl border bg-white p-4 shadow-sm" data-testid={`task-${t.request_id}`}>
      <div className="flex flex-wrap items-center justify-between gap-2"><b>كشف {t.ref_no ?? ''} — {t.type_name}</b><span className="text-xs font-bold">خطوة {t.step_no} من {t.total_steps}</span></div>
      <p className="mt-2 text-sm">{details?.target_label} {details?.amount != null ? `· ${fmtMoney(details.amount)} د.ع` : ''}</p>
      <button type="button" className="mt-3 rounded-xl bg-[#0b3d6b] px-4 py-2 text-sm font-bold text-white" data-testid={`disclosure-detail-${t.request_id}`} onClick={() => setOpen(true)}>عرض الكشف واتخاذ القرار</button>
      {open && <Suspense fallback={<LoadingSpinner />}><DisclosureDetailDrawer id={t.request_id} onClose={() => setOpen(false)} /></Suspense>}
    </li>
  )
}
/** 00398: مهمة «تصفير المنصة» — لا زر موافقة مباشر إطلاقاً؛ «إظهار تفاصيل التصفير» يفتح صفحة التفاصيل حيث الاعتماد بكلمة سر «اعتماد تصفير» أو الرفض بسبب */
function PlatformResetTaskCard({ t }: { t: ApprovalTask }) {
  const [open, setOpen] = useState(false)
  const d = t.details as PlatformResetTaskDetails | null
  return (
    <li className="rounded-2xl border-2 border-rose-300 bg-rose-50 p-4 shadow-sm" data-testid={`task-${t.request_id}`}>
      <div className="flex items-start justify-between gap-2">
        <div>
          <div className="text-sm font-black">{t.requester_name} <span className="rounded-full bg-white px-2 py-0.5 text-[10px] font-bold text-slate-700">{t.requester_role_label}</span></div>
          <div className="mt-1 text-sm font-black text-rose-900">⚠ طلب تصفير المنصة</div>
        </div>
        <span className="rounded-full bg-white px-2 py-0.5 text-[10px] font-bold text-[#0b3d6b]" data-testid={`task-step-${t.request_id}`}>خطوة {t.step_no} من {t.total_steps}</span>
      </div>
      <div className="mt-2 rounded-xl bg-white p-3 text-xs text-slate-800" data-testid={`task-reset-${t.request_id}`}>
        <div><b>{d?.categories_count ?? 0}</b> فئة بيانات · <b className="tabular-nums">{(d?.total_rows ?? 0).toLocaleString('en-US')}</b> سجل سيُحذف نهائياً{d?.includes_accounts ? ' · يشمل الحسابات' : ''}</div>
        {d?.labels && d.labels.length > 0 && <div className="mt-1 text-slate-600">{d.labels.slice(0, 6).join('، ')}{d.labels.length > 6 ? ` … و${d.labels.length - 6} أخرى` : ''}</div>}
        <div className="mt-1 text-[11px] font-bold text-rose-800">لا موافقة من هنا — افتح التفاصيل وراجع القائمة كاملة ثم اعتمد بكلمة السر أو ارفض.</div>
        <div className="mt-1 text-[11px] text-slate-500">قُدّم {timeAr(t.created_at)} · {dateAr(t.created_at)}</div>
      </div>
      <button type="button" data-testid={`reset-detail-${t.request_id}`} onClick={() => setOpen(true)} className="mt-3 h-11 w-full rounded-xl bg-rose-700 text-sm font-black text-white">إظهار تفاصيل التصفير</button>
      {open && <PlatformResetDetailView id={t.request_id} onClose={() => setOpen(false)} />}
    </li>
  )
}
function GenericTaskCard({ t }: { t: ApprovalTask }) {
  const decide = useDecideApproval()
  return <TaskCardInner t={t} d={{ pending: decide.isPending, approve: () => decide.mutate({ kind: t.request_kind, requestId: t.request_id, approve: true }), reject: (note, onSuccess) => decide.mutate({ kind: t.request_kind, requestId: t.request_id, approve: false, note }, { onSuccess }) }} />
}
function AdvanceTaskCard({ t }: { t: ApprovalTask }) {
  const decide = useDecideAdvance()
  return <TaskCardInner t={t} d={{ pending: decide.isPending, approve: (x) => decide.mutate({ id: t.request_id, approve: true, amount: x.amount, installments: x.installments }), reject: (note, onSuccess) => decide.mutate({ id: t.request_id, approve: false, note }, { onSuccess }) }} />
}

function TaskCardInner({ t, d }: { t: ApprovalTask; d: Decider }) {
  const [mode, setMode] = useState<'idle' | 'reject'>('idle'), [note, setNote] = useState(''), [showPath, setShowPath] = useState(false)
  const fallback = Boolean((t.details as { approval_fallback?: boolean } | null)?.approval_fallback)
  const timeline = useApprovalTimeline(showPath && !fallback ? t.request_kind : undefined, showPath && !fallback ? t.request_id : undefined)
  const isSupply = t.request_kind === 'supplies', isTermination = t.request_kind === 'termination', isAdvance = t.request_kind === 'advance', isCold = t.request_kind === 'cold_archive_purge', isReport = t.request_kind === 'complaint_report', isHire = t.request_kind === 'hire', isAttEdit = t.request_kind === 'attendance_edit'
  const cold = isCold ? (t.details as ColdPurgeTaskDetails | null) : null
  const rep = isReport ? (t.details as ComplaintReportTaskDetails | null) : null
  const term = isTermination ? (t.details as TerminationTaskDetails | null) : null
  const hireD = isHire ? (t.details as HireTaskDetails | null) : null
  const attD = isAttEdit ? (t.details as AttendanceEditTaskDetails | null) : null
  const adv = isAdvance ? (t.details as AdvanceTaskDetails | null) : null
  const bd = (t.request_kind === 'leave' || t.request_kind === 'time_permit') && (t.details as BackdatedTaskDetails | null)?.backdated ? (t.details as BackdatedTaskDetails) : null
  const [editAmount, setEditAmount] = useState(false), [amount, setAmount] = useState(''), [inst, setInst] = useState('')
  const pending = d.pending
  const approve = () => d.approve({ amount: isAdvance && editAmount && amount.trim() !== '' ? Number(amount) : null, installments: isAdvance && editAmount && inst.trim() !== '' ? Number(inst) : null })
  const reject = () => d.reject(note.trim(), () => setMode('idle'))
  const period = isSupply || isTermination || isAdvance || isCold || isReport || isHire || isAttEdit ? '' : t.request_kind === 'time_permit' ? `${dateAr(t.start_date)} · ${hm(t.start_time)}–${hm(t.end_time)} (${t.minutes} دقيقة)` : t.start_date === t.end_date ? `${dateAr(t.start_date)} (يوم واحد)` : `${dateAr(t.start_date)} → ${dateAr(t.end_date)} (${t.days} أيام)`
  return (
    <li className="rounded-2xl border bg-white p-4 shadow-sm" data-testid={`task-${t.request_id}`}>
      <div className="flex items-start justify-between gap-2">
        <div>
          <div className="text-sm font-black">{t.requester_name} <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-bold text-slate-700">{t.requester_role_label}</span></div>
          <div className="text-[11px] text-slate-500">{[t.parent_sector ? (PARENT_AR[t.parent_sector] ?? t.parent_sector) : null, t.area_name].filter(Boolean).join(' · ')}</div>
        </div>
        <span className="rounded-full bg-blue-50 px-2 py-0.5 text-[10px] font-bold text-[#0b3d6b]" data-testid={`task-step-${t.request_id}`}>خطوة {t.step_no} من {t.total_steps}</span>
      </div>
      <div className="mt-3 rounded-xl bg-slate-50 p-3 text-sm">
        <div className="font-black">{isSupply ? <><Package size={14} className="inline" /> {t.type_name} {t.ref_no && <span className="text-[11px] font-normal text-slate-500">· {t.ref_no}</span>}</> : isTermination ? <span className="text-rose-800"><UserX size={14} className="inline" /> {t.type_name} · {term?.type_label}</span>
          : isAdvance ? <span className="text-amber-800"><Wallet size={14} className="inline" /> {t.type_name} · {adv?.type_name} {t.ref_no && <span className="text-[11px] font-normal text-slate-500">· <span dir="ltr">{t.ref_no}</span></span>}</span>
          : isReport ? <span className="text-violet-900"><FileText size={14} className="inline" /> {t.type_name} · {rep?.title}</span>
          : isCold ? <span className="text-slate-800"><Archive size={14} className="inline" /> {t.type_name} {t.ref_no && <span className="text-[11px] font-normal text-slate-500">· <span dir="ltr">{t.ref_no}</span></span>}</span> : t.type_name}</div>
        {rep && <ComplaintReportDetails t={t} rep={rep} />}
        {cold && (
          <div className="mt-1 rounded-lg border border-slate-200 bg-white p-2 text-xs text-slate-800" data-testid={`task-cold-${t.request_id}`}>
            <div className="flex flex-wrap gap-x-3 gap-y-1">
              <span>الفترة: <b>{dateAr(cold.period_from)} → {dateAr(cold.period_to)}</b></span>
              <span>الملفات: <b className="tabular-nums">{cold.file_count}</b> ({(cold.total_bytes / 1_048_576).toFixed(1)} م.ب)</span>
              <span>النسخ المتحقَّقة: <b className="tabular-nums">{cold.verified_copies}/{cold.required_copies}</b>{cold.copies ? ` (${cold.copies})` : ''}</span>
            </div>
            {cold.by_source.length > 0 && <div className="mt-1 text-slate-600">المصادر: {cold.by_source.map((s) => `${s.source_key} (${s.files})`).join('، ')}</div>}
            <div className="mt-1 font-bold text-red-800">الموافقة تعني السماح بحذف هذه الصور من سحابة المنصة نهائياً (تبقى على القرص فقط). السجلات النصية لا تُمسّ.</div>
          </div>
        )}
        {attD ? (
          <div className="mt-1 rounded-lg border border-emerald-100 bg-white p-2 text-xs text-slate-800" data-testid={`task-attedit-${t.request_id}`}>
            <div className="font-black">{attD.scope_label}</div>
            <div className="text-slate-600">{attD.action_label}{attD.payload?.check_in ? ` · ${attD.payload.check_in} ← ${attD.payload.check_out ?? '—'}` : ''}{attD.payload?.status ? ` · ${attD.payload.status}` : ''}</div>
            <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-0.5 text-slate-700"><span className="flex items-center gap-1"><Clock size={12} /> {attD.dates.length <= 3 ? attD.dates.map((x) => dateAr(x)).join('، ') : `${dateAr(attD.dates[0] ?? null)} → ${dateAr(attD.dates[attD.dates.length - 1] ?? null)}`}</span><span>{attD.employees} موظف × {attD.days} يوم = <b>{attD.items}</b> يوم عمل</span></div>
            <div className="mt-1 text-[11px] text-slate-500">بعد موافقتك يصل الطلب إلى الموارد البشرية لمراجعة البنود واعتماد التنفيذ.</div>
          </div>
        ) : hireD ? (
          <div className="mt-1 rounded-lg border border-sky-100 bg-white p-2 text-xs text-slate-800" data-testid={`task-hire-${t.request_id}`}>
            <div className="font-black">{hireD.full_name}</div>
            <div className="text-slate-600">{hireD.job_title}{hireD.department ? ` · ${hireD.department}` : ''} · {hireD.source_label}</div>
            <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-0.5 text-slate-700"><span className="flex items-center gap-1"><Clock size={12} /> المباشرة: {dateAr(hireD.hire_date)}</span><span>العقد: {hireD.contract_label}</span>{hireD.shift_name && <span>الشفت: {hireD.shift_name}</span>}{hireD.phone && <span dir="ltr">{hireD.phone}</span>}</div>
            <div className="mt-1 text-[11px] text-slate-500">بلا رقم وظيفي — تكتبه الموارد البشرية وتُكمل الملف بعد الاعتماد؛ لا يُنشأ الموظف قبل ذلك.</div>
          </div>
        ) : term ? (
          <div className="mt-1 rounded-lg border border-rose-100 bg-white p-2 text-xs text-slate-800" data-testid={`task-termination-${t.request_id}`}>
            <div className="font-black">{term.target_name}</div>
            <div className="text-slate-600">{term.target_label}</div>
            <div className="mt-1 flex items-center gap-1 text-slate-700"><Clock size={12} /> آخر يوم عمل: {dateAr(term.last_day)}</div>
          </div>
        ) : adv ? (
          <div className="mt-1 rounded-lg border border-amber-100 bg-white p-2 text-xs text-slate-800" data-testid={`task-advance-${t.request_id}`}>
            <div className="font-black">{adv.employee_name} <span className="font-normal text-slate-500">{adv.employee_number ?? ''}</span></div>
            <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-slate-700">
              <span>المبلغ: <b className="tabular-nums" data-testid={`task-advance-amount-${t.request_id}`}>{fmtMoney(adv.amount)} د.ع</b>{adv.requested_amount !== adv.amount && <span className="text-slate-500"> (المطلوب أصلاً {fmtMoney(adv.requested_amount)})</span>}</span>
              <span>التسديد: <b>{adv.method_label}</b>{adv.method === 'equal' && adv.installments ? ` · ${adv.installments} شهراً` : adv.method === 'fixed' && adv.monthly_amount ? ` · ${fmtMoney(adv.monthly_amount)} شهرياً` : adv.method === 'percent' && adv.percent ? ` · ${adv.percent}%` : ''}</span>
              {adv.estimated_installment != null && adv.estimated_installment > 0 && <span>القسط الشهري التقديري: <b className="tabular-nums">{fmtMoney(adv.estimated_installment)}</b></span>}
            </div>
            {mode === 'idle' && (
              <div className="mt-2">
                {!editAmount ? (
                  <button type="button" data-testid={`advance-edit-${t.request_id}`} onClick={() => { setEditAmount(true); setAmount(String(adv.amount)); setInst(adv.installments ? String(adv.installments) : '') }} className="text-[11px] font-bold text-[#0b3d6b] underline">تعديل المبلغ{adv.method === 'equal' ? ' / عدد الأقساط' : ''} قبل الموافقة</button>
                ) : (
                  <div className="grid grid-cols-2 gap-2">
                    <label className="text-[11px] font-bold text-slate-700">المبلغ المعتمد (د.ع)
                      <input data-testid={`advance-amount-${t.request_id}`} type="number" inputMode="numeric" min={1} value={amount} onChange={(e) => setAmount(e.target.value)} className="mt-1 h-9 w-full rounded-lg border px-2 text-sm font-normal tabular-nums" />
                    </label>
                    {adv.method === 'equal' && (
                      <label className="text-[11px] font-bold text-slate-700">عدد الأقساط
                        <input data-testid={`advance-installments-${t.request_id}`} type="number" inputMode="numeric" min={1} max={60} value={inst} onChange={(e) => setInst(e.target.value)} className="mt-1 h-9 w-full rounded-lg border px-2 text-sm font-normal tabular-nums" />
                      </label>
                    )}
                    <button type="button" onClick={() => setEditAmount(false)} className="col-span-2 text-start text-[11px] text-slate-500 underline">إلغاء التعديل (الموافقة على المبلغ كما هو)</button>
                  </div>
                )}
              </div>
            )}
          </div>
        ) : isSupply ? (
          <ul className="mt-1 space-y-0.5 text-xs text-slate-800" data-testid={`task-items-${t.request_id}`}>
            {(t.items ?? []).map((it) => <li key={it.item_id} className="flex justify-between rounded-lg bg-white px-2 py-1"><span>{it.name}</span><b>{it.qty} {it.unit}</b></li>)}
          </ul>
        ) : isCold || isReport ? null : <div className="mt-0.5 flex items-center gap-1 text-slate-700"><Clock size={14} />{period}</div>}
        {bd && (
          <div className="mt-2 rounded-lg border border-amber-300 bg-amber-50 p-2 text-xs text-amber-900" data-testid={`task-backdated-${t.request_id}`}>
            <div className="font-black">⚠ طلب بأثر رجعي — قُدِّم بعد اليوم بـ <span dir="ltr">{bd.days_late}</span> {bd.days_late === 1 ? 'يوم' : 'أيام'}</div>
            <div className="mt-0.5">سبب التأخر: «{bd.reason}»</div>
            <div className="mt-0.5 flex flex-wrap gap-x-3">
              <span>الحالة المسجّلة لذلك اليوم: <b>{bd.prior_status ? (ATTENDANCE_STATUS_LABELS[bd.prior_status as keyof typeof ATTENDANCE_STATUS_LABELS] ?? bd.prior_status) : 'لا سجل بعد'}</b> ⇐ عند الموافقة تُصحَّح تلقائياً ويُلغى الاستقطاع</span>
              <span className={bd.month_count >= bd.alert_threshold ? 'font-black text-red-700' : ''} data-testid={`task-backdated-count-${t.request_id}`}>طلبات بأثر رجعي هذا الشهر: <span dir="ltr">{bd.month_count}</span>{bd.month_count >= bd.alert_threshold ? ' — بلغ حد التنبيه' : ''}</span>
            </div>
          </div>
        )}
        {t.notes && <div className="mt-1 text-xs text-slate-600">{isTermination ? 'السبب: ' : ''}«{t.notes}»</div>}
        <div className="mt-1 text-[11px] text-slate-500">قُدّم {timeAr(t.created_at)} · {dateAr(t.created_at)}</div>
      </div>
      {t.previous_steps.length > 0 && (
        <ul className="mt-2 space-y-1 text-[11px]" data-testid={`task-prev-${t.request_id}`}>
          {t.previous_steps.map((p) => (
            <li key={p.step_no} className="flex items-center gap-1 text-slate-600">
              {p.status === 'approved' ? <CheckCircle2 size={12} className="text-emerald-600" /> : <span className="inline-block size-3 rounded-full bg-slate-300" />}
              {p.step_no}. {p.label}: {STATUS_AR[p.status] ?? p.status}{p.decided_by ? ` — ${p.decided_by}` : ''}{p.note ? ` («${p.note}»)` : ''}
            </li>
          ))}
        </ul>
      )}
      {mode === 'idle' ? (
        <div className="mt-3 grid grid-cols-2 gap-2">
          <button type="button" data-testid={`approve-${t.request_id}`} disabled={pending} onClick={approve}
            className="h-11 rounded-xl bg-emerald-600 text-sm font-black text-white disabled:opacity-40"><CheckCircle2 size={16} className="inline" /> موافقة</button>
          <button type="button" data-testid={`reject-${t.request_id}`} onClick={() => setMode('reject')} className="h-11 rounded-xl border border-rose-300 bg-rose-50 text-sm font-black text-rose-800"><XCircle size={16} className="inline" /> رفض</button>
        </div>
      ) : (
        <div className="mt-3 rounded-xl border border-rose-200 bg-rose-50 p-3">
          <label className="text-xs font-bold text-rose-900">سبب الرفض (إلزامي)
            <textarea data-testid={`reject-reason-${t.request_id}`} value={note} onChange={(e) => setNote(e.target.value)} rows={2} className="mt-1 w-full rounded-xl border px-3 py-2 text-sm font-normal" />
          </label>
          <div className="mt-2 grid grid-cols-2 gap-2">
            <button type="button" data-testid={`reject-confirm-${t.request_id}`} disabled={note.trim().length < 2 || pending}
              onClick={reject}
              className="h-10 rounded-xl bg-rose-600 text-sm font-black text-white disabled:opacity-40">تأكيد الرفض</button>
            <button type="button" onClick={() => setMode('idle')} className="h-10 rounded-xl border bg-white text-sm font-bold">إلغاء</button>
          </div>
        </div>
      )}
      <button type="button" data-testid={`path-${t.request_id}`} onClick={() => setShowPath((v) => !v)} className="mt-2 text-[11px] font-bold text-[#0b3d6b] underline">{showPath ? 'إخفاء مسار الطلب' : 'عرض مسار الطلب كاملاً'}</button>
      {showPath && (
        <ol className="mt-2 space-y-1 rounded-xl border p-2 text-[11px]" data-testid={`path-list-${t.request_id}`}>
          {fallback && <li>1. {t.step_label} — بانتظار القرار</li>}
          {(timeline.data ?? []).map((s) => (
            <li key={s.step_no} className="flex flex-wrap items-center gap-1">
              <b>{s.step_no}.</b> {s.step_label} — <span className={s.status === 'approved' ? 'text-emerald-700' : s.status === 'rejected' ? 'text-rose-700' : s.status === 'pending' ? 'text-amber-700' : 'text-slate-500'}>{STATUS_AR[s.status]}</span>
              {s.approvers.length > 0 && <span className="text-slate-500">({s.approvers.map((a) => a.name).join('، ')})</span>}
            </li>
          ))}
        </ol>
      )}
    </li>
  )
}

/** 00339: تفاصيل تقرير شكاوى + تنزيل ملف العرض (سياسة التخزين تسمح للموافق أثناء مهمته فقط) */
function ComplaintReportDetails({ t, rep }: { t: ApprovalTask; rep: ComplaintReportTaskDetails }) {
  const download = useComplaintReportDownload()
  const [err, setErr] = useState('')
  const open = (url: string) => { const a = document.createElement('a'); a.href = url; a.rel = 'noopener noreferrer'; a.click() }
  return (
    <div className="mt-1 rounded-lg border border-violet-100 bg-white p-2 text-xs text-slate-800" data-testid={`task-report-${t.request_id}`}>
      <div className="flex flex-wrap gap-x-3 gap-y-1">
        <span>القاطع: <b>{rep.sector_label}</b></span>
        <span>تاريخ التقرير: <b>{dateAr(rep.report_date)}</b></span>
        <span>المواقع المضمّنة: <b className="tabular-nums">{rep.items}</b></span>
        <span>النوع: <b>{rep.scope === 'email' ? 'ردّ على بريد' : 'يومي'}</b></span>
      </div>
      {rep.recipients.length > 0 && <div className="mt-1 text-slate-600" dir="ltr">{rep.recipients.join(', ')}</div>}
      <div className="mt-2 flex flex-wrap items-center gap-2">
        {rep.pptx_path && <button type="button" data-testid={`report-download-${t.request_id}`} disabled={download.isPending} onClick={() => download.mutate(rep.pptx_path as string, { onSuccess: open, onError: () => setErr('تعذر تجهيز رابط التنزيل؛ أعد المحاولة.') })} className="inline-flex items-center gap-1 rounded-lg border border-violet-300 bg-violet-50 px-2 py-1 font-bold text-violet-900 disabled:opacity-40"><Download size={12} /> تنزيل ملف العرض للمراجعة</button>}
        <span className="text-slate-600">راجع الغلاف والجدول وصور قبل/بعد قبل الاعتماد — الاعتماد يسمح بإرساله إلى الجهة المرسلة.</span>
      </div>
      {err && <p className="mt-1 text-red-700">{err}</p>}
    </div>
  )
}
